const posts = $json.hits || [];

if (posts.length === 0) {
  return [{ hasResults: false, topics: [] }];
}

const wordBoundaryAI = /\bAI\b/i;

const ranked = posts
  .filter(p => wordBoundaryAI.test(p.title))
  .map(p => ({
    title: p.title,
    score: p.points,
    permalink: 'https://news.ycombinator.com/item?id=' + p.objectID
  }))
  .sort((a, b) => b.score - a.score)
  .slice(0, 3);

return [{ hasResults: ranked.length > 0, topics: ranked }];

const topic = $json.title;
const permalink = $json.permalink;

const promptText = `You are a social media copywriter for an AI tools and automation brand. Turn the trending topic below into ready-to-post captions.

Topic: ${topic}

Write two captions:

1. TWITTER/X: under 280 characters, punchy and direct, no engagement-bait clichés ("You won't believe...", "Thread below"), 0-2 relevant hashtags maximum only if genuinely fitting.

2. LINKEDIN: 80-150 words, professional but not corporate-stiff, written like a practitioner sharing a real observation, ends with a light question or discussion prompt, no hashtags, no emojis.

For EACH caption, also write a matching image generation prompt: a concrete visual description (subject, style, mood, composition) suitable for an AI image generator, under 40 words, no text-in-image requests.

Output ONLY valid JSON, no markdown fences, no preamble, in this exact structure:
{"twitter": {"caption": "...", "imagePrompt": "..."}, "linkedin": {"caption": "...", "imagePrompt": "..."}}`;

return {
  json: {
    topic: topic,
    permalink: permalink,
    requestBody: {
      contents: [
        { role: "user", parts: [ { text: promptText } ] }
      ],
      generationConfig: {
        responseMimeType: "application/json",
        maxOutputTokens: 2000,
        temperature: 0.7
      }
    }
  }
};

const responseItems = $input.all();
const requestItems = $('Build Caption Request').all();
const output = [];

for (let i = 0; i < responseItems.length; i++) {
  const raw = responseItems[i].json.candidates?.[0]?.content?.parts?.[0]?.text;
  const topic = requestItems[i].json.topic;
  const sourceUrl = requestItems[i].json.permalink;

  if (!raw) {
    throw new Error('Caption generation returned no content for topic: ' + topic);
  }

  const cleaned = raw.replace(/```json|```/g, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    throw new Error('Caption response was not valid JSON: ' + cleaned.slice(0, 200));
  }

  if (!parsed.twitter?.caption || !parsed.linkedin?.caption) {
    throw new Error('Caption response was missing required fields');
  }

  const now = new Date().toISOString();

  output.push({
    json: {
      dateAdded: now,
      topic: topic,
      platform: 'Twitter',
      caption: parsed.twitter.caption,
      imagePrompt: parsed.twitter.imagePrompt,
      status: 'Draft',
      sourceUrl: sourceUrl
    }
  });

  output.push({
    json: {
      dateAdded: now,
      topic: topic,
      platform: 'LinkedIn',
      caption: parsed.linkedin.caption,
      imagePrompt: parsed.linkedin.imagePrompt,
      status: 'Draft',
      sourceUrl: sourceUrl
    }
  });
}

return output;

